package org.sleepwell.app;
import android.app.Activity;import android.content.Intent;import android.os.*;import android.graphics.*;import android.view.*;import android.widget.*;import androidx.activity.*;import java.util.*;import org.json.*;
/** Visible, explicit camera brightness challenge and the identical silent preview. */
public final class CameraLightActivity extends ComponentActivity {
 static final int CHALLENGE=796,FALLBACK=RESULT_FIRST_USER;
 private String request,run,mode,status="Camera stays off until you start.",error="";private int unit,level;private boolean resumed,pending,done,math;private long generation,started;private CameraLightCamera.Port camera;private CameraLightHold hold;private TextView live;private final Handler handler=new Handler(Looper.getMainLooper());
 static Intent preview(Activity a,int level){return RecordUi.intent(a,CameraLightActivity.class).putExtra("mode","preview").putExtra("level",level).putExtra("request",UUID.randomUUID().toString());}
 static Intent challenge(Activity a,String run,int unit,String nonce,int level){return RecordUi.intent(a,CameraLightActivity.class).putExtra("mode","challenge").putExtra("run",run).putExtra("unit",unit).putExtra("request",nonce).putExtra("level",level);}
 @Override public void onCreate(Bundle saved){super.onCreate(saved);RecordUi.review(this);try{request=getIntent().getStringExtra("request");if(request==null||!UUID.fromString(request).toString().equals(request))throw new IllegalArgumentException();mode=getIntent().getStringExtra("mode");if(!Set.of("preview","challenge").contains(mode))throw new IllegalArgumentException();run=mode.equals("preview")?request:getIntent().getStringExtra("run");unit=mode.equals("preview")?0:getIntent().getIntExtra("unit",-1);level=getIntent().getIntExtra("level",-1);hold=new CameraLightHold(level);if(run==null||run.isBlank()||run.length()>128||unit<0)throw new IllegalArgumentException();if(saved!=null){done=saved.getBoolean("done");math=saved.getBoolean("math");error=saved.getString("error","");status="Camera paused. Start again when ready.";}}catch(Exception invalid){finish();return;}if(mode.equals("challenge")){setShowWhenLocked(true);setTurnScreenOn(true);getWindow().addFlags(WindowManager.LayoutParams.FLAG_KEEP_SCREEN_ON);}getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){public void handleOnBackPressed(){back();}});render();}
 private boolean current(){if(!resumed||isDestroyed()||isFinishing())return false;if(mode.equals("preview"))return true;try{if(!AlarmService.current(this,run)||Prefs.number(this,"challengeCompleted",-1)!=unit)return false;Alarm active=Alarm.read(new JSONObject(Prefs.text(this,"active_alarm","{}")));ChallengeRoutine.Position position=active.challenges().at(unit);return position!=null&&position.task.type.equals("Camera light")&&position.task.rounds==level;}catch(Exception invalid){return false;}}
 private final Runnable verify=new Runnable(){public void run(){if(!resumed)return;if(!current()){stop();setResult(RESULT_CANCELED);finish();return;}if(camera!=null&&SystemClock.elapsedRealtime()-started>=60000){stop();error="The one-minute attempt ended. Retry or use Math.";render();}handler.postDelayed(this,250);}};
 private void render(){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,mode.equals("preview")?"Camera light preview":"Find a bright light",this::back);Design.space(body,12);if(done){Design.text(body,math?"Math alternative completed":"Brightness held",25,600,Design.INK);Design.button(body,"Try again",false,()->{done=math=false;status="Camera stays off until you start.";render();});Design.fixedAction(body,"Return",this::back);return;}if(math){WakePuzzleView.math(body,run,unit,level-1,()->current()&&hasWindowFocus(),()->{done=true;render();});return;}Design.text(body,"Point the center square toward a room light or bright window. Hold image brightness above "+CameraLightHold.percent(level)+"% for 1.2 seconds.",15,400,Design.MUTED);Design.space(body,8);Design.text(body,"Image brightness is relative, not lux. Camera exposure and framing affect it. No images are saved or uploaded. Avoid pointing at the sun.",12,400,Design.MUTED);Design.space(body,12);FrameLayout frame=new FrameLayout(this);frame.setBackground(Design.shape(this,Design.SOFT,18));frame.setClipToOutline(true);frame.setContentDescription("Camera preview with central brightness measurement square");if(camera!=null){View preview=camera.preview();if(preview.getParent() instanceof ViewGroup parent)parent.removeView(preview);frame.addView(preview,new FrameLayout.LayoutParams(-1,-1));frame.addView(new Reticle(this),new FrameLayout.LayoutParams(-1,-1));}else{TextView empty=Design.text(this,"Camera is paused",15,500,Design.MUTED);empty.setGravity(Gravity.CENTER);frame.addView(empty,new FrameLayout.LayoutParams(-1,-1));}int side=Math.min(Design.dp(this,300),Math.max(1,getResources().getDisplayMetrics().widthPixels-Design.dp(this,56)));LinearLayout.LayoutParams square=new LinearLayout.LayoutParams(side,side);square.gravity=Gravity.CENTER_HORIZONTAL;body.addView(frame,square);Design.space(body,12);live=Design.text(body,status,14,500,Design.BROWN);live.setContentDescription("Camera brightness status");live.setAccessibilityLiveRegion(View.ACCESSIBILITY_LIVE_REGION_POLITE);if(camera==null){CameraLightCameraAccess.Status permission=CameraLightCameraAccess.status(this);String label=permission==CameraLightCameraAccess.Status.NEEDED?"Allow brightness camera":permission==CameraLightCameraAccess.Status.SETTINGS?"Open camera settings":"Start brightness camera";Button start=Design.button(body,label,true,this::startPressed);if(permission==CameraLightCameraAccess.Status.UNSUPPORTED){start.setEnabled(false);Design.text(body,"A camera is unavailable. Use Math instead.",13,400,Design.MUTED);}}else Design.button(body,"Pause brightness camera",false,()->{stop();status="Camera paused. Start again when ready.";render();});LinearLayout footer=RecordUi.footer(body);if(!error.isEmpty())Design.text(footer,error,13,500,0xffa93919);Design.button(footer,"Use Math instead",false,this::chooseMath);}
 private void startPressed(){if(!current()||done||math)return;error="";CameraLightCameraAccess.Status permission=CameraLightCameraAccess.status(this);if(permission==CameraLightCameraAccess.Status.READY){pending=false;begin();return;}if(permission==CameraLightCameraAccess.Status.UNSUPPORTED){error="A camera is required. Use Math instead.";render();return;}pending=true;try{CameraLightCameraAccess.request(this);}catch(RuntimeException failure){pending=false;error="Camera permission settings could not open. Use Math or retry.";render();}}
 private void begin(){if(!current()||done||math||CameraLightCameraAccess.status(this)!=CameraLightCameraAccess.Status.READY)return;if(!stop()){error="Camera cleanup failed. Return and choose Math.";render();return;}long ticket=++generation;try{camera=CameraLightCamera.factory.create(this);started=SystemClock.elapsedRealtime();status="Aim the center square toward light.";camera.start(new CameraLightCamera.Listener(){public void frame(double brightness,long captured,String issue){if(ticket!=generation||camera==null||!current()||!hasWindowFocus())return;if(CameraLightCameraAccess.status(CameraLightActivity.this)!=CameraLightCameraAccess.Status.READY){stop();error="Camera permission changed. Allow it again or use Math.";render();return;}if(hold.frame(brightness,captured,SystemClock.elapsedRealtime())){respond(RESULT_OK,captured);return;}status=Double.isFinite(brightness)?Math.round(brightness*100/255)+"% brightness · target "+CameraLightHold.percent(level)+"% · hold "+hold.progress()+"%":issue==null||issue.isBlank()?"Waiting for a fresh camera reading.":issue;if(live!=null)live.setText(status);}public void error(String message){if(ticket!=generation||!current())return;stop();error=message;render();}});render();}catch(RuntimeException failure){stop();error="The brightness camera could not start. Retry or use Math.";render();}}
 private boolean stop(){generation++;if(hold!=null)hold.reset();if(camera!=null)try{camera.close();camera=null;}catch(RuntimeException failure){return false;}return true;}
 private void chooseMath(){if(!current())return;if(!stop()){error="Camera cleanup failed. Return and choose Math from the alarm.";render();return;}pending=false;if(mode.equals("preview")){math=true;render();}else respond(FALLBACK,0);}
 private void respond(int result,long captured){if(!current()||!stop())return;if(mode.equals("preview")){done=true;render();return;}setResult(result,new Intent().putExtra("run",run).putExtra("unit",unit).putExtra("request",request).putExtra("level",level).putExtra("captured",captured));finish();}
 private void back(){pending=false;stop();setResult(RESULT_CANCELED);finish();}
 @Override protected void onResume(){super.onResume();resumed=true;if(!current()){finish();return;}verify.run();if(pending&&CameraLightCameraAccess.status(this)==CameraLightCameraAccess.Status.READY){pending=false;begin();}else if(camera==null)render();}
 @Override protected void onPause(){resumed=false;handler.removeCallbacks(verify);stop();super.onPause();}
 @Override public void onRequestPermissionsResult(int code,String[] permissions,int[] results){super.onRequestPermissionsResult(code,permissions,results);if(code!=CameraLightCameraAccess.REQUEST)return;if(CameraLightCameraAccess.status(this)==CameraLightCameraAccess.Status.READY){pending=true;if(resumed){pending=false;begin();}}else{pending=false;error="Camera access was not allowed. Use Math or allow it in settings.";render();}}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);else if(camera!=null){stop();status="Camera paused. Start again when ready.";if(resumed)render();}}
 @Override protected void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);saved.putBoolean("done",done);saved.putBoolean("math",math);saved.putString("error",error);}
 @Override protected void onDestroy(){handler.removeCallbacksAndMessages(null);stop();super.onDestroy();}
 private static final class Reticle extends View {final Paint pen=new Paint(Paint.ANTI_ALIAS_FLAG);Reticle(android.content.Context context){super(context);setImportantForAccessibility(IMPORTANT_FOR_ACCESSIBILITY_NO);}protected void onDraw(Canvas canvas){pen.setColor(0xffead9ff);pen.setStrokeWidth(Design.dp(getContext(),2));pen.setStyle(Paint.Style.STROKE);canvas.drawRect(getWidth()*.25f,getHeight()*.25f,getWidth()*.75f,getHeight()*.75f,pen);}}
}
